namespace Core.Entities
{
    public class Business
    {
        public Guid Id { get; set; }
        /// <summary>
        /// Stable public identifier generated by SQL Server, not an authorization credential.
        /// </summary>
        public string PublicId { get; set; } = null!;
        public string UserId { get; set; } = null!;
        public User User { get; set; } = null!;
        public string BusinessName { get; set; } = string.Empty;
        public string? BusinessLogoUrl { get; set; }
        /// <summary>
        /// Display-only short code (e.g., HT, TC, GY).
        /// NOT trusted, NOT used for security or logic
        /// </summary>
        public string BusinessCode { get; set; } = "XX";
        /// <summary>
        /// IANA TimeZone (e.g. Australia/Sydney, Asia/Seoul, America/New_York)
        /// Used for date range calculation (Today, Settlement, Reports)
        /// </summary>
        public string TimeZone { get; set; } = string.Empty;
        public string CountryCode { get; set; } = string.Empty;
        public string BaseCurrency { get; set; } = string.Empty;
        public bool IsActive { get; set; }
        public DateTimeOffset DateCreated { get; set; }
        public DateTimeOffset DateUpdated { get; set; }
        public DateTimeOffset? DeletedAt { get; set; }
        public ICollection<BusinessReceiveAddress> ReceiveAddresses { get; set; } = [];
        public ICollection<BusinessAllowToken> AllowTokens { get; set; } = [];
        public ICollection<CryptoPayment> CryptoPayments { get; set; } = [];
    }
}
